{
  "task_summary": "Predict whether an individual’s income exceeds the ACS threshold using demographic, education, work, and occupation-related features.",
  "ranking": [
    {
      "rank": 1,
      "feature_id": 7,
      "rationale": "Usual hours worked is a direct, stable proxy for labor supply and strongly predicts income across states."
    },
    {
      "rank": 2,
      "feature_id": 2,
      "rationale": "Educational attainment is one of the most robust cross-state predictors of earnings and human capital."
    },
    {
      "rank": 3,
      "feature_id": 4,
      "rationale": "Occupation captures job type and pay structure, which are highly predictive though somewhat granular."
    },
    {
      "rank": 4,
      "feature_id": 1,
      "rationale": "Class of worker reflects employment arrangement and wage patterns that generalize reasonably well."
    },
    {
      "rank": 5,
      "feature_id": 0,
      "rationale": "Age is strongly related to labor-market experience and earnings, with broad portability across states."
    },
    {
      "rank": 6,
      "feature_id": 3,
      "rationale": "Marital status can correlate with labor supply and household economics, but is more indirect and demographic."
    },
    {
      "rank": 7,
      "feature_id": 8,
      "rationale": "Sex may carry predictive signal through labor-market differences, but it is a demographic shortcut and less desirable."
    },
    {
      "rank": 8,
      "feature_id": 6,
      "rationale": "Relationship to householder can proxy household composition and dependency status, but is only weakly tied to income."
    },
    {
      "rank": 9,
      "feature_id": 9,
      "rationale": "Race can correlate with income through structural factors, but it is a sensitive demographic shortcut and less stable."
    },
    {
      "rank": 10,
      "feature_id": 5,
      "rationale": "Place of birth is the most geography- and cohort-linked feature, making it brittle and least semantically portable."
    }
  ]
}
